/**
 * Karla, as font data the OG card can actually render with.
 *
 * `next/og` rasterizes through Satori, which does NOT inherit the page's CSS
 * fonts — it only draws with font binaries handed to `ImageResponse`, falling
 * back to its bundled Noto Sans otherwise. That fallback is why the social card
 * once rendered in a typeface that appears nowhere else in the product.
 *
 * TTF, not the .woff2 next/font produces: Satori reads TTF, OTF and WOFF, and
 * cannot decode WOFF2 at all. So this is fetched from Google Fonts rather than
 * lifted out of .next/static/media.
 *
 * Embedded base64 for the same reason the logo is (see opengraph-image.tsx):
 * `public/` is never bundled into Vercel's serverless function and build
 * tracing didn't reliably include co-located files, so anything read from disk
 * at runtime threw ENOENT in production. A string constant is just JS.
 *
 * Replaces the Manrope pair this used to carry. Manrope is still the PRINTED
 * card's face; Karla is the app's, and a social card is the app talking.
 */

export const OPENGRAPH_KARLA_REGULAR_BASE64 =
  "";

export const OPENGRAPH_KARLA_EXTRABOLD_BASE64 =
  "";
